// Enumerate legal triples; simultaneously price compatible seven-row pairs across triples by bitset intersection. A pair survives iff both rows survive edits and every original seven missed by both is destroyed. For vertex v every endpoint needs exactly 8-deg(v) mutually compatible rows containing v. Fail fast on lowest degrees. Survivors still need full global panel check. The degree condition is a necessary bound, not a construction.
use std::io::{self,BufRead};type B=Vec<u64>;fn inds(mut x:u32)->impl Iterator<Item=usize>{std::iter::from_fn(move||if x==0{None}else{let j=x.trailing_zeros() as usize;x&=x-1;Some(j)})}fn cl(p:&[usize],need:usize,adj:&[Vec<u64>])->bool{if need==0{return true}for(k,&v)in p.iter().enumerate(){if p.len()-k<need{return false}if need==1{return true}let rest:Vec<_>=p[k+1..].iter().copied().filter(|&i|adj[v][i/64]>>(i%64)&1!=0).collect();if cl(&rest,need-1,adj){return true}}false}
fn run(a:&[u32]){let mut sets=vec![0u32];for(i,v)in a.iter().enumerate(){let n=sets.len();for j in 0..n{if sets[j]&v==0{sets.push(sets[j]|1<<i)}}}let q:Vec<_>=sets.into_iter().filter(|s|s.count_ones()==7).collect();let mut ed=vec![];for i in 0..26{for j in 0..i{if a[i]>>j&1==0&&a[i]&a[j]==0{ed.push((i,j))}}}let mut cases=vec![];for i in 0..ed.len(){for j in 0..i{for k in 0..j{let mut g=a.to_vec();let mut ok=true;for h in [i,j,k]{let(x,y)=ed[h];if g[x]&g[y]!=0{ok=false;break}g[x]|=1<<y;g[y]|=1<<x}if ok{cases.push((1u64<<i|1u64<<j|1u64<<k,g))}}}}let costs:Vec<_>=q.iter().map(|s|ed.iter().enumerate().filter(|(_, &(x,y))|s>>x&1!=0&&s>>y&1!=0).fold(0u64,|v,(i,_)|v|1<<i)).collect();let mut vs:Vec<_>=(0..26).collect();vs.sort_by_key(|&i|a[i].count_ones());let mut trace=vec![cases.len()];for v in vs{if cases.is_empty(){break}let n=cases.len();let w=(n+63)/64;let mut killed=vec![vec![0u64;w];q.len()];for(j,&co)in costs.iter().enumerate(){for(i,(m,_))in cases.iter().enumerate(){if m&co!=0{killed[j][i/64]|=1<<(i%64)}}}let mut sorted:Vec<_>=(0..q.len()).collect();sorted.sort_by_key(|&i|costs[i].count_ones());let rows:Vec<_>=(0..q.len()).filter(|&i|q[i]>>v&1!=0).collect();let mut edges=vec![Vec::new();n];let mut reps=vec![Vec::new();n];for(i,&s)in rows.iter().enumerate(){for(j,&t)in rows[..=i].iter().enumerate(){let mut b:B=killed[s].iter().zip(&killed[t]).map(|(x,y)|!(x|y)).collect();if n%64!=0{b[w-1]&=(1<<(n%64))-1}for &h in &sorted{if q[h]&(q[s]|q[t])!=0{continue}let mut any=0;for (x,z)in b.iter_mut().zip(&killed[h]){*x&=z;any|=*x}if any==0{break}}for (k,&z)in b.iter().enumerate(){let mut x=z;while x!=0{let id=64*k+x.trailing_zeros()as usize;x&=x-1;if i==j{reps[id].push(i)}else{edges[id].push((i,j))}}}}}let mut rem=vec![];for(id,(m,g))in cases.into_iter().enumerate(){let need=8-g[v].count_ones()as usize;let mut adj=vec![vec![0u64;(rows.len()+63)/64];rows.len()];for &(i,j)in &edges[id]{adj[i][j/64]|=1<<(j%64);adj[j][i/64]|=1<<(i%64)}let p:Vec<_>=(0..rows.len()).filter(|&i|m&costs[rows[i]]==0&&adj[i].iter().map(|x|x.count_ones()as usize).sum::<usize>()+1>=need).collect();if !reps[id].is_empty()||cl(&p,need,&adj){rem.push((m,g))}}cases=rem;trace.push(cases.len())}eprintln!("{:?}",trace);for(_,g) in cases{println!("{}",g.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(" "))}}
fn main(){for l in io::stdin().lock().lines(){let a:Vec<u32>=l.unwrap().split_whitespace().map(|z|z.parse().unwrap()).collect();assert_eq!(a.iter().map(|v|v.count_ones()).sum::<u32>(),146);run(&a)}}
